from pathlib import Path
import json
root=Path(__file__).resolve().parent; out=root/'research/outputs/sapa_wellbeing_terrain_explorer'; data=json.loads((out/'wellbeing_surface_bundle.json').read_text())
html='''<!doctype html><html><head><meta charset="utf-8"><title>SAPA Wellbeing Terrain</title><script src="https://cdn.plot.ly/plotly-2.35.2.min.js"></script><style>:root{color-scheme:dark}body{margin:0;background:#111;color:#eee;font:14px system-ui}header{padding:16px 22px;background:#181818;border-bottom:1px solid #333}h1{margin:0;font-size:20px;font-weight:500}header p{margin:3px 0;color:#aaa}.topbar{display:flex;gap:18px;align-items:center;margin-top:12px;flex-wrap:wrap}.topbar label{color:#bbb}.topbar select{background:#222;color:#eee;border:1px solid #555;padding:7px;min-width:190px}.layout{display:grid;grid-template-columns:180px 1fr 220px;min-height:780px}.left,.right{padding:18px;background:#151515;border-right:1px solid #2d2d2d}.right{border-right:0;border-left:1px solid #2d2d2d}.left h3,.right h3{font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:#aaa;margin:0 0 14px}.left label{display:block;color:#bbb;margin:12px 0 5px}.left select,.left button{width:100%;background:#222;color:#eee;border:1px solid #555;padding:7px}.center{padding:8px 14px}.note{color:#aaa;font-size:12px;line-height:1.45;margin:8px 0}.dial{margin:18px 0}.dial label{display:flex;justify-content:space-between;color:#bbb}.dial input{width:100%;accent-color:#78b7c9}.dial output{color:#eee}.toggle{display:block;margin:12px 0;color:#ccc}.toggle input{accent-color:#78b7c9}#plot{height:690px}#details{font-size:12px;line-height:1.5;color:#bbb;border-top:1px solid #333;padding-top:12px}@media(max-width:900px){.layout{grid-template-columns:150px 1fr}.right{grid-column:1/-1;border-left:0;border-top:1px solid #2d2d2d;display:flex;gap:20px;flex-wrap:wrap}.right .dial{width:180px;margin:4px 0}#plot{height:560px}}</style></head><body><header><h1>SAPA Human Wellbeing Terrain</h1><p>Aggregate human wellbeing across the frozen SAPA Big Five terrain</p><div class="topbar"><label>Wellbeing indicator <select id="outcome"></select></label><label><input type="checkbox" id="advanced"> Advanced measures</label><span id="status"></span></div></header><div class="layout"><aside class="left"><h3>Axes and surface</h3><label>X axis<select id="x"></select></label><label>Y axis<select id="y"></select></label><label>Landscape<select id="mode"><option value="empirical">Observed / marginal</option><option value="conditional">Conditional 5D model</option></select></label><label>View<select id="view"><option value="3d">3D surface</option><option value="2d">2D heatmap</option></select></label><label class="toggle"><input type="checkbox" id="trend"> Trend plane</label><label class="toggle"><input type="checkbox" id="zero" checked> Sample-mean plane</label><button id="reset">Reset view</button><p class="note">Changing the wellbeing indicator preserves the selected X/Y axes and camera orientation.</p></aside><main class="center"><div id="plot"></div><div id="details"></div></main><aside class="right"><h3>Orientation dials</h3><div class="dial"><label>Yaw <output id="yawv">45°</output></label><input id="yaw" type="range" min="0" max="360" value="45"></div><div class="dial"><label>Pitch <output id="pitchv">30°</output></label><input id="pitch" type="range" min="5" max="85" value="30"></div><div class="dial"><label>Roll <output id="rollv">0°</output></label><input id="roll" type="range" min="-180" max="180" value="0"></div><div class="dial"><label>Zoom <output id="zoomv">1.0×</output></label><input id="zoom" type="range" min="0.6" max="2" step=".05" value="1"></div><p class="note">Dials control the Plotly camera. The camera is preserved while outcomes change.</p></aside></div><script>const B=__BUNDLE__,axes=B.axes,xs=document.getElementById('x'),ys=document.getElementById('y'),os=document.getElementById('outcome'),details=document.getElementById('details'),status=document.getElementById('status'),vals={};axes.forEach(a=>{xs.add(new Option(a,a));ys.add(new Option(a,a));vals[a]=0});xs.value='Extraversion';ys.value='Emotional Stability';const cc={};B.grid.forEach(r=>cc[r.outcome]=(cc[r.outcome]||0)+1);const primary=['content_balanced_ge2','affect','appraisal','meaning_making','self_concept','interpersonal_relationships'],advanced=['content_balanced_ge3','historical_13','non_affect','vitality'];function fill(){const keep=document.getElementById('advanced').checked?primary.concat(advanced):primary;const old=os.value;os.innerHTML='';keep.forEach(o=>os.add(new Option(B.outcomes[o].label,o)));if(keep.includes(old))os.value=old;else os.value='content_balanced_ge2'}fill();function cam(){const yaw=+yawEl.value*Math.PI/180,pitch=+pitchEl.value*Math.PI/180,zoom=+zoomEl.value;return {eye:{x:zoom*Math.cos(yaw),y:zoom*Math.sin(yaw),z:zoom*Math.sin(pitch)+.35}}}const yawEl=document.getElementById('yaw'),pitchEl=document.getElementById('pitch'),rollEl=document.getElementById('roll'),zoomEl=document.getElementById('zoom');function dials(){['yaw','pitch','roll','zoom'].forEach(k=>document.getElementById(k+'v').textContent=k==='zoom'?zoomEl.value+'×':document.getElementById(k).value+'°')}function draw(){dials();const x=xs.value,y=ys.value,o=os.value,m=document.getElementById('mode').value,v=document.getElementById('view').value,d=B.outcomes[o],rows=B.grid.filter(r=>r.outcome===o&&r.x===x&&r.y===y);details.innerHTML='<b>'+d.label+'</b><br>Outcome-available respondents: '+d.N+'<br>Supported cells (all axis pairs): '+(cc[o]||0)+'<br>Lens: '+(d.details.lens||'—')+'<br>Content: '+(d.details.content||'—')+'<br>Items: '+(d.details.items||'—')+'<br><span class="note">'+(d.details.caveat||'')+'</span>';if(!rows.length){status.textContent='No supported cells for this outcome/axis pair (N≥10).';Plotly.purge('plot');return}const c=B.coefficients[o],X=rows.map(r=>r.x_value),Y=rows.map(r=>r.y_value),Z=rows.map(r=>m==='empirical'?r.mean:c.intercept+c.coef[axes.indexOf(x)]*r.x_value+c.coef[axes.indexOf(y)]*r.y_value+axes.reduce((s,a,i)=>s+(a!==x&&a!==y?c.coef[i]*vals[a]:0),0)),ux=[...new Set(X)].sort((a,b)=>a-b),uy=[...new Set(Y)].sort((a,b)=>a-b),zm=uy.map(yy=>ux.map(xx=>{const i=rows.findIndex(r=>r.x_value===xx&&r.y_value===yy);return i<0?null:Z[i]})),tr=[v==='3d'?{x:ux,y:uy,z:zm,type:'surface',name:'Wellbeing',colorscale:'RdBu',cmin:-2,cmax:2}:{x:ux,y:uy,z:zm,type:'heatmap',name:'Wellbeing',colorscale:'RdBu',zmin:-2,zmax:2}];if(rows.length<25)tr.push(v==='3d'?{x:X,y:Y,z:Z,type:'scatter3d',mode:'markers',name:'Supported cells',marker:{size:5,color:Z,colorscale:'RdBu'}}:{x:X,y:Y,mode:'markers',name:'Supported cells',marker:{size:9,color:Z,colorscale:'RdBu'}});if(document.getElementById('zero').checked)tr.push(v==='3d'?{x:ux,y:uy,z:uy.map(()=>ux.map(()=>0)),type:'surface',name:'Sample mean',opacity:.2,showscale:false,colorscale:[[0,'#777'],[1,'#777']]}:{x:ux,y:uy,z:uy.map(()=>ux.map(()=>0)),type:'contour',name:'Sample mean',showscale:false,line:{color:'#777',dash:'dot'}});if(document.getElementById('trend').checked){const tz=uy.map(yy=>ux.map(xx=>c.intercept+c.coef[axes.indexOf(x)]*xx+c.coef[axes.indexOf(y)]*yy));tr.push(v==='3d'?{x:ux,y:uy,z:tz,type:'surface',name:'Trend plane',opacity:.35,showscale:false,colorscale:[[0,'#444'],[1,'#444']]}:{x:ux,y:uy,z:tz,type:'contour',name:'Trend plane',showscale:false,line:{color:'#333',dash:'dash'}})}Plotly.react('plot',tr,{title:(m==='conditional'?'Conditional 5D estimate':'Observed marginal mean')+' — '+d.label,xaxis:{title:x+' (standardized)'},yaxis:{title:y+' (standardized)'},scene:{xaxis:{title:x},yaxis:{title:y},zaxis:{title:d.label+' (centered)'},camera:cam()},margin:{l:50,r:20,t:50,b:45}},{responsive:true});status.textContent='N='+d.N+' | '+(cc[o]<500?'Sparse outcome; suppressed regions remain blank.':'')+(m==='conditional'?' model-estimated slice':' observed sample average')}[xs,ys,os,document.getElementById('mode'),document.getElementById('view'),document.getElementById('trend'),document.getElementById('zero')].forEach(e=>e.addEventListener('change',draw));document.getElementById('advanced').addEventListener('change',()=>{fill();draw()});[yawEl,pitchEl,rollEl,zoomEl].forEach(e=>e.addEventListener('input',draw));document.getElementById('reset').onclick=()=>{yawEl.value=45;pitchEl.value=30;rollEl.value=0;zoomEl.value=1;draw()};draw();</script></body></html>'''.replace('__BUNDLE__',json.dumps(data,separators=(',',':')))
html=html.replace('<aside class="left"><h3>Axes and surface</h3>','<aside class="left"><h3>Axes and surface</h3><div id="sliders" class="panel"></div>')
slider_js="function sliders(){const s=document.getElementById('sliders');s.innerHTML='<b>Hidden traits (conditional mode)</b>';axes.filter(a=>a!==xs.value&&a!==ys.value).forEach(a=>{const l=document.createElement('label');l.textContent=a+' ';const i=document.createElement('input');i.type='range';i.min=-2.5;i.max=2.5;i.step=.05;i.value=vals[a];i.disabled=document.getElementById('mode').value!=='conditional';i.oninput=()=>{vals[a]=+i.value;draw()};l.append(i);s.append(l)})}"
html=html.replace('function draw(){',slider_js+'function draw(){')
(out/'sapa_wellbeing_terrain_explorer.html').write_text(html)
